## Output Validation Pipeline
import json
import re
from pydantic import BaseModel, validator
from typing import Optional, List
class AgentToolCall(BaseModel):
tool_name: str
parameters: dict
reasoning: Optional[str]
@validator('tool_name')
def validate_tool_allowed(cls, v):
allowed_tools = ["search", "read_file", "calculator", "get_weather"]
if v not in allowed_tools:
raise ValueError(f"Tool '{v}' is not in allowed list")
return v
@validator('parameters')

def validate_no_sensitive_data(cls, v):
sensitive_patterns = [
r'api[_-]?key', r'password', r'secret', r'token',
r'credential', r'private[_-]?key'
]
params_str = json.dumps(v).lower()
for pattern in sensitive_patterns:
if re.search(pattern, params_str):
raise ValueError("Parameters contain potentially sensitive data")
return v
class OutputGuardrails:
def __init__(self):
self.pii_patterns = self._load_pii_patterns()
self.blocked_actions = set()
self.rate_limiter = RateLimiter(max_calls=100, window_seconds=60)
async def validate_output(self, agent_output: dict) -> dict:
# Check rate limits
if not self.rate_limiter.allow():
raise RateLimitExceeded("Agent action rate limit exceeded")
# Validate structure
if "tool_calls" in agent_output:
for call in agent_output["tool_calls"]:
validated = AgentToolCall(**call)
# Filter PII from responses
if "response" in agent_output:
agent_output["response"] = self._filter_pii(agent_output["response"])
# Check for data exfiltration patterns
if self._detect_exfiltration_attempt(agent_output):
raise SecurityViolation("Potential data exfiltration detected")
return agent_output
def _detect_exfiltration_attempt(self, output: dict) -> bool:
"""Detect attempts to exfiltrate data through tool calls."""
suspicious_patterns = [
# Encoding sensitive data in URLs
lambda o: "http" in str(o) and any(
p in str(o).lower() for p in ["base64", "encode", "password"]
),
# Large data in webhook/API calls
lambda o: o.get("tool_name") in ["http_request", "webhook"] and
len(str(o.get("parameters", ""))) > 10000,
]
return any(pattern(output) for pattern in suspicious_patterns)

## Rate Limiting and Resource Protection

## Implement Request Rate Limiting
Protect services from request flooding and resource exhaustion. The example below limits unary RPCs only. Apply stream admission limits through a
stream interceptor and enforce per-message limits within the stream; limiting stream creation alone does not limit the messages sent over an existing
stream.
// Go - Illustrative unary rate limiting with bounded entry count
import (
"golang.org/x/time/rate"
"sync"
"time"
)
type RateLimiterStore struct {
limiters map[string]*rateLimiterEntry
mu 	sync.RWMutex
}
type rateLimiterEntry struct {
limiter *rate.Limiter
lastSeen time.Time
}
var store = &RateLimiterStore{
limiters: make(map[string]*rateLimiterEntry),
}
func rateLimitInterceptor(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (interface{}, error) {
clientIP := getClientIP(ctx)
store.mu.Lock()
entry, exists := store.limiters[clientIP]
if !exists {
if len(store.limiters) >= maxLimiterEntries {
store.mu.Unlock()
return nil, status.Error(codes.ResourceExhausted, "limiter capacity reached")
}
entry = &rateLimiterEntry{
limiter: rate.NewLimiter(rate.Limit(10), 20), // 10 req/sec, burst 20
lastSeen: time.Now(),
}
store.limiters[clientIP] = entry
}
entry.lastSeen = time.Now()
store.mu.Unlock()
if !entry.limiter.Allow() {
return nil, status.Errorf(codes.ResourceExhausted, "rate limit exceeded")
}
return handler(ctx, req)
}
// Cleanup old limiters periodically
func cleanupOldLimiters() {
store.mu.Lock()
defer store.mu.Unlock()
cutoff := time.Now().Add(-time.Hour)
for ip, entry := range store.limiters {
if entry.lastSeen.Before(cutoff) {
delete(store.limiters, ip)
}
}
}
Configure maxLimiterEntries as a positive cap based on the process memory budget. Schedule cleanupOldLimiters as part of the service lifecycle; defining
it does not run it. At capacity, this illustration rejects new client keys while retaining existing limits, so monitor saturation and its effect on legitimate
clients. Derive client keys from a trusted connection or authenticated identity, not arbitrary forwarded headers.
Each rate.Limiter limits events for one key; it does not bound the number of keys in the map. This store is local to one process. Use a maintained shared
rate-limiting service when limits must apply across replicas.

